     $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name'])?:'application/octet-stream';$allowedMime=['pdf'=>['application/pdf'],'docx'=>['application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/zip'],'pptx'=>['application/vnd.openxmlformats-officedocument.presentationml.presentation','application/zip'],'txt'=>['text/plain','application/octet-stream'],'md'=>['text/plain','text/markdown','application/octet-stream'],'png'=>['image/png'],'jpg'=>['image/jpeg'],'jpeg'=>['image/jpeg'],'webp'=>['image/webp']];if(!in_array($mime,$allowedMime[$ext],true))throw new RuntimeException('File content does not match an allowed document MIME type.');
     $stored=bin2hex(random_bytes(32));$dest=$config['storage'].'/uploads/'.$stored.'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dest))throw new RuntimeException('Could not safely store the upload.');
     try{$ex=(new Extractor())->extract($dest,$ext);$status='success';$txt=$ex['text'];$err=null;}catch(Throwable $e){$status='failed';$txt='';$err=$e->getMessage();}
     $title=trim(pathinfo($name,PATHINFO_FILENAME));$s=db()->prepare('INSERT INTO handouts(title,original_name,stored_name,mime_type,file_size,extraction_status,extraction_error,extracted_text) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$title,$name,$stored.'.'.$ext,$mime,$f['size'],$status,$err,$txt]);$id=(int)db()->lastInsertId();redirect('?page=handout&id='.$id);
   }
   if($action==='delete_handout'){ $h=must((int)$_POST['id'],'handouts');db()->prepare('DELETE FROM handouts WHERE id=?')->execute([$h['id']]);$path=$config['storage'].'/uploads/'.$h['stored_name'];if(is_file($path))unlink($path);redirect('?'); }
   if($action==='generate'){
