     $count=max(1,min(60,(int)($_POST['count']??30)));$difficulty=in_array($_POST['difficulty']??'', ['Easy','Moderate','Hard','Mixed'],true)?$_POST['difficulty']:'Mixed';$mode=in_array($_POST['mode']??'', ['practice','exam','explanations','flashcards','cram','repeat'],true)?$_POST['mode']:'practice';$types=array_values(array_intersect((array)($_POST['types']??[]),['multiple_choice','true_false','identification','short_answer']));if(!$types)$types=['multiple_choice'];
     $text=(string)$h['extracted_text'];$section=trim((string)($_POST['section']??''));if($section!==''){$start=mb_stripos($text,$section);if($start===false)throw new RuntimeException('That section or topic could not be found confidently. Select text from the preview or use a matching heading.');$text=mb_substr($text,max(0,$start-400),12000);}
     if($mode==='repeat'){
