     foreach($items as $i=>$q){$key=['answer'=>$q['answer']];if(in_array($q['type'],['identification','short_answer'],true))$key=['answer'=>$q['answer'],'accepted'=>[$q['answer']]];$qins->execute([$qid,substr((string)$q['id'],0,80),$i+1,$q['type'],strtolower($q['difficulty']),$q['question'],json_encode($q['options'],JSON_UNESCAPED_UNICODE),json_encode($key,JSON_UNESCAPED_UNICODE),$q['explanation'],$q['grading_notes']??'',json_encode($q['sources'],JSON_UNESCAPED_UNICODE),'needs_review']);}
