<?php elseif($page==='history'):$rows=db()->query('SELECT q.*,h.title handout_title,(SELECT COUNT(*) FROM attempts a WHERE a.quiz_id=q.id) attempts FROM quizzes q JOIN handouts h ON h.id=q.handout_id ORDER BY q.created_at DESC')->fetchAll();?>
<section class="card"><h1>Quiz history</h1><?php if(!$rows):?><p>No generated quizzes yet. Upload a handout to get started.</p><?php else:foreach($rows as $r):?><article class="question"><h3><?=Security::e($r['title'])?></h3><p><?=Security::e($r['handout_title'])?> · <?=Security::e($r['mode'])?> · <?=Security::e($r['created_at'])?> · <?=$r['attempts']?> attempts</p><div class="row"><a class="button" href="?page=quiz&id=<?=$r['id']?>">Open</a><form method="post" data-confirm="Delete this quiz and its saved attempts?"><input type="hidden" name="_csrf" value="<?=Security::e($csrf)?>"><input type="hidden" name="action" value="delete_quiz"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger">Delete</button></form></div><?php $as=db()->prepare('SELECT * FROM attempts WHERE quiz_id=? ORDER BY submitted_at DESC');$as->execute([$r['id']]);foreach($as as $a):?><p><a href="?page=result&id=<?=$a['id']?>">Attempt <?=Security::e($a['submitted_at'])?> — <?=number_format((float)$a['score'],1)?>%</a></p><?php endforeach;?></article><?php endforeach;endif;?></section>
<?php elseif($page==='settings'):?><section class="card"><h1>Settings and setup verification</h1><p>Provider selection and credentials are read by PHP on the server, never sent to the browser.</p><ul><li>Configured provider: <?=Security::e($config['provider'])?></li><li>Configured model: <?=Security::e($config[$config['provider']==='gemini'?'gemini_model':'openai_model'])?></li><li>Provider key present: <?=($config[$config['provider']==='gemini'?'gemini_key':'openai_key']!=='')?'Yes':'No'?></li><li>PDO MySQL: <?=extension_loaded('pdo_mysql')?'available':'missing'?></li><li>cURL: <?=extension_loaded('curl')?'available':'missing'?></li><li>mbstring: <?=extension_loaded('mbstring')?'available':'missing'?></li><li>DOM/XML: <?=extension_loaded('dom')&&extension_loaded('xml')?'available':'missing'?></li><li>Zip: <?=class_exists(ZipArchive::class)?'available':'missing'?></li><li>Storage writable: <?=is_writable($config['storage'])?'yes':'no'?></li></ul><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e($csrf)?>"><input type="hidden" name="action" value="test_provider"><button>Test provider connection</button></form><p class="notice">Provider pricing, rate limits, and account eligibility vary; AI usage is not guaranteed to be free.</p></section>
<?php else:$hands=db()->query('SELECT id,title,original_name,extraction_status,created_at FROM handouts ORDER BY created_at DESC')->fetchAll();?><section class="card"><h1>Your study desk</h1><p>Build practice sets only from the handouts you upload. Extracted text is shown for review before any AI request.</p><div class="row"><a class="button" href="?page=upload">Upload a handout</a><a class="button secondary" href="?page=history">View quiz history</a></div></section><section class="card"><h2>Handouts</h2><?php if(!$hands):?><p>No handouts yet. Upload a PDF, Office document, text file, or image.</p><?php else:?><div class="grid"><?php foreach($hands as $h):?><article class="card"><h3><?=Security::e($h['title'])?></h3><p><?=Security::e($h['original_name'])?></p><span class="badge"><?=Security::e($h['extraction_status'])?></span><p><a class="button" href="?page=handout&id=<?=$h['id']?>">Preview</a> <a class="button secondary" href="?page=configure&id=<?=$h['id']?>">Configure</a></p></article><?php endforeach;?></div><?php endif;?></section><?php endif;?></main><footer>Local personal-use software. Not hardened for public internet deployment. No analytics or tracking.</footer><script src="public/assets/js/app.js"></script><script>document.querySelector('#generate-form')?.addEventListener('submit',()=>{const w=document.querySelector('#working');if(w)w.hidden=false;});</script></body></html>
